-- Tournaments (brackets + Apex-style points). Run in the D1 console before pushing.
CREATE TABLE IF NOT EXISTS tournaments ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, game TEXT NOT NULL, format TEXT NOT NULL, team_size INTEGER NOT NULL, max_teams INTEGER NOT NULL, starts_at INTEGER NOT NULL, rules TEXT, prize_coins INTEGER NOT NULL DEFAULT 0, points_config TEXT, status TEXT NOT NULL DEFAULT 'signup', winner_team_id INTEGER, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, finished_at INTEGER );
CREATE TABLE IF NOT EXISTS tournament_teams ( id INTEGER PRIMARY KEY AUTOINCREMENT, tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, name TEXT NOT NULL, captain_id INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS tournament_members ( tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, team_id INTEGER NOT NULL REFERENCES tournament_teams(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (tournament_id, user_id) );
CREATE TABLE IF NOT EXISTS tournament_matches ( id INTEGER PRIMARY KEY AUTOINCREMENT, tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, round INTEGER NOT NULL, slot INTEGER NOT NULL, team_a INTEGER, team_b INTEGER, score_a INTEGER, score_b INTEGER, winner INTEGER, UNIQUE (tournament_id, round, slot) );
CREATE TABLE IF NOT EXISTS tournament_results ( id INTEGER PRIMARY KEY AUTOINCREMENT, tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, game_no INTEGER NOT NULL, team_id INTEGER NOT NULL REFERENCES tournament_teams(id) ON DELETE CASCADE, placement INTEGER NOT NULL, kills INTEGER NOT NULL DEFAULT 0, UNIQUE (tournament_id, game_no, team_id) );
CREATE TABLE IF NOT EXISTS tournament_prizes ( tournament_id INTEGER NOT NULL REFERENCES tournaments(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, place INTEGER NOT NULL, coins INTEGER NOT NULL, PRIMARY KEY (tournament_id, user_id) );
